+        assertThat(in.tryReadStringFromBytes(bytes, 0, 10, 8), is("€3456789"));
+        verify(in).skip(10);
+        clearInvocations(in);
+
+        // not enough bytes to read all chars
+        assertNull(in.tryReadStringFromBytes(bytes, 0, 10, 9));
+        verify(in, never()).skip(anyLong());
+    }
+
